4	---
5	
6	# KMP Dependency Injection
7	
8	Cross-platform dependency injection with Koin.
9	
10	## Koin Multiplatform Setup
11	
12	### Dependencies
13	
14	```kotlin
15	// build.gradle.kts (shared module)
16	sourceSets {
17	    val commonMain by getting {
18	        dependencies {
19	            implementation("io.insert-koin:koin-core:${koinVersion}")
20	            implementation("io.insert-koin:koin-test:${koinVersion}")
21	        }
22	    }
23	    val androidMain by getting {
24	        dependencies {
25	            implementation("io.insert-koin:koin-android:${koinVersion}")
26	        }
27	    }
28	}
29	```
30	
31	### Module Definition
32	
33	```kotlin
34	// commonMain/kotlin/di/AppModule.kt
35	val sharedModule = module {
36	    // ViewModels (Android) / ScreenModels (multiplatform)
37	    factory { HomeViewModel(get(), get()) }
38	    factory { DetailViewModel(get()) }
39	
40	    // Use Cases
41	    factory { GetUsersUseCase(get()) }
42	    factory { GetUserDetailUseCase(get()) }
43	
44	    // Repositories
45	    single<UserRepository> { UserRepositoryImpl(get(), get()) }
46	
47	    // Data Sources
48	    single { UserApi(get()) }
49	    single { createDatabase(get()) }
50	}
51	```
52	
53	### Platform Modules
54	
55	```kotlin
56	// androidMain/kotlin/di/PlatformModule.kt
57	val androidPlatformModule = module {
58	    includes(sharedModule)
59	
60	    // Android-specific dependencies
61	    single { android.content.Context() }
62	    single { PlatformConnectivityMonitor(get()) }
63	    single { PlatformFileService(get()) }
64	}
65	
66	// iosMain/kotlin/di/PlatformModule.kt
67	val iosPlatformModule = module {
68	    includes(sharedModule)
69	
70	    // iOS-specific dependencies
71	    single { PlatformConnectivityMonitor() }
72	    single { PlatformFileService() }
73	}
74	```
75	
76	## Koin Start
77	
78	### Android
79	
80	```kotlin
81	// androidMain/kotlin/MyApp.kt
82	class MyApp : Application() {
83	    override fun onCreate() {
84	        super.onCreate()
85	        startKoin {
86	            androidContext(this@MyApp)
87	            modules(androidPlatformModule)
88	        }
89	    }
90	}
91	```
92	
93	### iOS
94	
95	```kotlin
96	// iosMain/kotlin/di/KoinInit.kt
97	fun initKoin() {
98	    startKoin {
99	        modules(iosPlatformModule)
100	    }
101	}
102	
103	// Called from Swift
104	// KotlinKMMSharedKt.doInitKoin()
105	```
106	
107	### Compose Multiplatform
108	
109	```kotlin
110	// commonMain/kotlin/Main.kt
111	fun main() {
112	    startKoin {
113	        modules(sharedModule)
114	    }
115	
116	    App()
117	}
118	```
119	
120	## ViewModel Injection
121	
122	### Android (ViewModel)
123	
124	```kotlin
125	// androidMain/kotlin/ui/HomeScreen.kt
126	@Composable
127	fun HomeScreen(
128	    viewModel: HomeViewModel = koinViewModel()
129	) {
130	    val state by viewModel.state.collectAsStateWithLifecycle()
131	    HomeContent(state)
132	}
133	```
134	
135	### iOS (ScreenModel)
136	
137	```kotlin
138	// commonMain/kotlin/ui/HomeScreen.kt
139	@Composable
140	fun HomeScreen() {
141	    val model = getScreenModel<HomeScreenModel>()
142	    val state by model.state.collectAsState()
143	
144	    HomeContent(state)
145	}
146	```
